import {Renderer} from './renderer.js';
import {mp4Type} from './recording.js';
import {VolumeFrame} from './frame.js';
import {dimensions} from './math.js';
import {bindRange,speedMultiplier,advanceScan} from './controls.js';
const $=id=>document.getElementById(id);
const s={position:0,rx:0,ry:0,rz:0,effect:0,waveAngle:0,amplitude:.22,frequency:3,phase:0,decay:.6,centerX:0,centerY:0,animationSpeed:.12,depth:.85,density:1.65,layers:56,clip:0,renderQuality:1,outputAR:'source',outputRes:960,fit:'fit',zoom:1};
const defaults={...s};
let clipSeconds=6,scanRate=1;
let renderer,dirty=true,busy=false,job=0,stream=null,frozen=false,sourceURL=null,recordURL=null,recorder=null,recordStream=null,recordStart=0,recordChunks=[],scan=false,scanDirection=1,spin=[0,0],liveCallback=null,liveTimer=null,lastLive=-1,writeHead=0,liveInterval=0,framesRendered=0,lastStats=0,lastRender=0,lastTime=0;
const sliders=new Map(),video=$('source'),volumeFrame=new VolumeFrame($('axes'));
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function fail(e){console.error(e);status(e.message??String(e),true);}
function slider(group,key,label,min,max,step,suffix=''){
 const angle=['rx','ry','rz','waveAngle'].includes(key),anchor=defaults[key];
 const node=document.createElement('div');node.className='slider';
 node.innerHTML=`<div class="slider-row"><label for="range-${key}">${label}</label><span class="slider-value"><output></output><button type="button" class="slider-reset" title="Reset: ${anchor}${suffix}" aria-label="Reset ${label}">↺</button></span></div><div class="range-track"><input id="range-${key}" type="range" min="${min}" max="${max}" step="${step}" aria-label="${label}"><i class="range-anchor" style="left:calc(7px + (100% - 14px) * ${(anchor-min)/(max-min)})"></i></div>`;
 const input=node.querySelector('input'),out=node.querySelector('output');
 function sync(){input.value=s[key];out.textContent=Number(s[key]).toFixed(angle?1:step>=1?0:2)+suffix;input.setAttribute('aria-valuetext',out.textContent);}
 const change=value=>{s[key]=value;sync();dirty=true;if(angle&&key!=='waveAngle')document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('active'));};
 bindRange(input,{anchor,threshold:angle?.7:key==='zoom'?.012:0,angle,onChange:change});
 node.querySelector('button').onclick=()=>change(defaults[key]);
 if(angle)input.title='Ctrl: 5° steps. Arrow keys: fine adjustment. Ctrl + wheel: adjust; plain wheel scrolls.';
 $(group).append(node);sliders.set(key,{sync,input});sync();
}
slider('sliceControls','position','Position',-1,1,.001);
for(const[k,l]of[['rx','Tilt X'],['ry','Tilt Y'],['rz','Rotation Z']])slider('sliceControls',k,l,-180,180,.1,'°');
slider('effectControls','amplitude','Amplitude',0,.9,.01);slider('effectControls','frequency','Frequency',.2,12,.1);slider('effectControls','phase','Phase',0,1,.001,' turns');slider('effectControls','waveAngle','Wave direction',-180,180,.1,'°');slider('effectControls','decay','Ripple falloff',0,4,.05);slider('effectControls','centerX','Ripple center X',-1,1,.01);slider('effectControls','centerY','Ripple center Y',-1,1,.01);slider('animationControls','animationSpeed','Animation speed',-1,1,.01,' cyc/s');
slider('volumeControls','density','History opacity',0,6,.05);slider('volumeControls','layers','Visible frames',8,128,1);slider('volumeControls','depth','Time axis depth',.2,2,.01);slider('outputControls','zoom','Scale',.4,3,.01);
function syncSpeed(){scanRate=speedMultiplier(Number($('scanSpeed').value));$('scanSpeedValue').textContent=scanRate.toFixed(3)+'×';$('scanSpeed').setAttribute('aria-valuetext',scanRate.toFixed(3)+'×');$('scanTiming').textContent=busy?'Preparing…':(clipSeconds/scanRate).toFixed(2)+' s / scan';}
bindRange($('scanSpeed'),{anchor:0,threshold:.007,onChange:syncSpeed});
$('resetSpeed').onclick=()=>{$('scanSpeed').value=0;syncSpeed();};syncSpeed();
function sync(){sliders.forEach(x=>x.sync());dirty=true;}
for(const id of ['clip','renderQuality','outputAR','outputRes','fit'])$(id).onchange=()=>{s[id]=['clip','renderQuality','outputRes'].includes(id)?Number($(id).value):$(id).value;dirty=true;};
function updateEffectControls(){
 const n=s.effect;
 for(const key of ['amplitude','frequency','phase','waveAngle','decay','centerX','centerY','animationSpeed']){
  const enabled=key==='waveAngle'?n===1:['decay','centerX','centerY'].includes(key)?n===3:key==='animationSpeed'?n!==0&&$('animate').checked:n!==0;
  const row=sliders.get(key).input.closest('.slider');row.classList.toggle('disabled',!enabled);row.setAttribute('aria-disabled',String(!enabled));row.querySelectorAll('input,button').forEach(el=>el.disabled=!enabled);
 }
 $('animate').disabled=n===0;$('animate').closest('label').classList.toggle('disabled',n===0);
}
function selectEffect(n){s.effect=n;document.querySelectorAll('[data-effect]').forEach(b=>b.classList.toggle('active',Number(b.dataset.effect)===n));updateEffectControls();dirty=true;}
$('animate').addEventListener('change',updateEffectControls);
document.querySelectorAll('[data-effect]').forEach(b=>b.onclick=()=>selectEffect(Number(b.dataset.effect)));
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{s.position=0;[s.rx,s.ry,s.rz]=({xy:[0,0,0],xt:[90,0,0],yt:[0,90,0],oblique:[28,-38,0]})[b.dataset.preset];document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));sync();});
$('resetSlice').onclick=()=>{Object.assign(s,{position:0,rx:0,ry:0,rz:0,amplitude:.22,frequency:3,phase:0,waveAngle:0,centerX:0,centerY:0,zoom:1});selectEffect(0);document.querySelector('[data-preset="xy"]').click();sync();};
function toggleSpin(){spin=spin.some(Boolean)?[0,0]:[.25,0];$('spin').classList.toggle('active',spin.some(Boolean));}
$('spin').onclick=toggleSpin;$('home').onclick=()=>{renderer.yaw=.62;renderer.pitch=.20;renderer.distance=4.2;spin=[0,0];$('spin').classList.remove('active');dirty=true;};
$('scan').onclick=()=>{scan=!scan;$('scanLabel').textContent=scan?'Pause scan':'Play scan';$('scanIcon').setAttribute('d',scan?'M3 2 H6 V14 H3 Z M10 2 H13 V14 H10 Z':'M4 2 L13 8 L4 14 Z');$('scan').setAttribute('aria-pressed',String(scan));$('scan').classList.toggle('active',scan);};
let drag=null;const volume=$('volume');volume.onpointerdown=e=>{volume.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,time:performance.now(),v:[0,0]};spin=[0,0];$('spin').classList.remove('active');};volume.onpointermove=e=>{if(!drag||!renderer)return;const now=performance.now(),dt=Math.max(.008,(now-drag.time)/1000),dx=(e.clientX-drag.x)*.006,dy=(e.clientY-drag.y)*.006;renderer.yaw-=dx;renderer.pitch+=dy;drag={x:e.clientX,y:e.clientY,time:now,v:[-dx/dt,dy/dt]};dirty=true;};volume.onpointerup=e=>{if(drag&&e.shiftKey){spin=drag.v.map(v=>Math.max(-2,Math.min(2,v)));$('spin').classList.toggle('active',spin.some(Boolean));}drag=null;};volume.onpointercancel=()=>drag=null;volume.onwheel=e=>{e.preventDefault();if(renderer)renderer.distance=Math.max(2.5,Math.min(9,renderer.distance*Math.exp(e.deltaY*.001)));dirty=true;};volume.addEventListener('wheel',()=>{},{passive:false});volume.onkeydown=e=>{if(e.code==='Space'){e.preventDefault();toggleSpin();}};
function fitOutputFrame(){const wrap=$('outputFrame').parentElement,ar=$('output').width/$('output').height,w=Math.max(1,Math.min(wrap.clientWidth-32,(wrap.clientHeight-32)*ar));const frame=$('outputFrame');frame.style.width=w+'px';frame.style.height=w/ar+'px';}
new ResizeObserver(()=>{dirty=true;fitOutputFrame();}).observe(volume);
new ResizeObserver(fitOutputFrame).observe($('outputFrame').parentElement);
function setBusy(v,text=''){busy=v;syncSpeed();$('empty').hidden=!v;$('cancel').hidden=!v;$('loadText').textContent=text;for(const id of ['demo','camera','rebuild','record','snapshot','quality','start','duration','file'])$(id).disabled=v;video.controls=false;$('progress').value=0;}
function waitEvent(target,event,token,timeout=20000){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>done(Error('The video timed out. Try an MP4/H.264 or WebM file.')),timeout);const ok=()=>done();const bad=()=>done(Error('This browser could not decode the video. Try MP4/H.264 or WebM.'));function done(err){clearTimeout(timer);target.removeEventListener(event,ok);target.removeEventListener('error',bad);if(token!==job)reject(new DOMException('Cancelled','AbortError'));else if(err)reject(err);else resolve();}target.addEventListener(event,ok,{once:true});target.addEventListener('error',bad,{once:true});});}
function stopLive(){if(liveCallback!==null&&video.cancelVideoFrameCallback)video.cancelVideoFrameCallback(liveCallback);clearTimeout(liveTimer);liveCallback=null;liveTimer=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;$('camera').textContent='Webcam';$('camera').classList.remove('active');$('freeze').hidden=true;$('start').disabled=false;frozen=false;}
function allocation(live=false){const[edge,frames]=$('quality').value.split(',').map(Number),[w,h]=dimensions(video.videoWidth,video.videoHeight,edge);const duration=Math.max(.5,Math.min(30,Number($('duration').value)||6));$('duration').value=duration;const n=live?Math.min(frames,Math.ceil(duration*30)):frames;renderer.alloc(w,h,n);volumeFrame.reset();const work=document.createElement('canvas');work.width=w;work.height=h;const ctx=work.getContext('2d',{alpha:false});ctx.translate(0,h);ctx.scale(1,-1);$('memory').textContent=`${w} × ${h} × ${n} · ${(w*h*n*4/1048576).toFixed(0)} MiB frame storage`;$('sourceAR').textContent=`${video.videoWidth} × ${video.videoHeight}`;return {work,ctx,w,h,n,duration};}
async function build(token){video.pause();setBusy(true,'Decoding frames…');const{work,ctx,w,h,n,duration}=allocation();const max=Math.max(0,video.duration-.05);const start=Math.max(0,Math.min(Number($('start').value)||0,Math.max(0,max-.05)));$('start').value=start.toFixed(2);const end=Math.min(max,start+duration);if(!Number.isFinite(end)||end<=start)throw Error('This video is too short or has no decodable frames.');for(let i=0;i<n;i++){if(token!==job)throw new DOMException('Cancelled','AbortError');const t=start+(end-start)*i/(n-1);if(Math.abs(video.currentTime-t)>.0001||video.readyState<2){const ready=waitEvent(video,'seeked',token);video.currentTime=t;await ready;}ctx.drawImage(video,0,0,w,h);renderer.upload(work,i);if(i%8===0)volumeFrame.observe(work);renderer.count=i+1;clipSeconds=Math.max(.001,t-start);syncSpeed();dirty=true;$('progress').value=(i+1)/n;$('loadText').textContent=`Frame ${i+1} / ${n} · ${(end-start).toFixed(1)} s`;if(i%8===0)await new Promise(r=>setTimeout(r,0));}video.currentTime=start;setBusy(false);status(`Volume ready: ${start.toFixed(1)}–${end.toFixed(1)} s · ${n} frames. All video processing stays on your device.`);dirty=true;}
async function load(src,name,isDemo=false){const token=++job;stopLive();video.pause();setBusy(true,'Reading video…');$('sourceName').textContent=name;$('credit').hidden=!isDemo;try{const ready=waitEvent(video,'loadeddata',token);video.src=src;video.load();await ready;await build(token);}catch(e){if(token!==job)return;setBusy(false);if(e.name!=='AbortError')fail(e);}}
$('demo').onclick=()=>load('demo.mp4','Demo / SHVETS production',true);
$('file').onchange=()=>{const f=$('file').files[0];if(!f)return;if(sourceURL)URL.revokeObjectURL(sourceURL);sourceURL=URL.createObjectURL(f);$('start').value=0;load(sourceURL,f.name);$('file').value='';};
$('cancel').onclick=()=>{job++;video.pause();setBusy(false);dirty=true;status(renderer.count?'Import stopped. The frames already loaded are available.':'Import cancelled. Open another video.');};
$('rebuild').onclick=async()=>{if(stream){startCamera();return;}if(!video.videoWidth)return;const token=++job;try{await build(token);}catch(e){if(token===job){setBusy(false);if(e.name!=='AbortError')fail(e);}}};
async function startCamera(){const token=++job;stopLive();setBusy(true,'Waiting for camera access…');let acquired=null;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access requires HTTPS or localhost.');acquired=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});if(token!==job){acquired.getTracks().forEach(t=>t.stop());return;}stream=acquired;video.removeAttribute('src');video.srcObject=stream;await video.play();if(!video.videoWidth)await waitEvent(video,'loadeddata',token);const{work,ctx,w,h,n,duration}=allocation(true);writeHead=0;lastLive=-1;liveInterval=duration*1000/n;clipSeconds=duration;syncSpeed();setBusy(false);$('start').disabled=true;$('camera').textContent='Stop webcam';$('camera').classList.add('active');$('freeze').hidden=false;$('freeze').textContent='Freeze buffer';$('sourceName').textContent='Webcam · rolling history';$('credit').hidden=true;status('Camera connected. The frame buffer fills as new frames arrive.');const capture=now=>{if(!stream||token!==job)return;if(!frozen&&video.readyState>=2&&(lastLive<0||now-lastLive>=liveInterval)){ctx.drawImage(video,0,0,w,h);try{renderer.upload(work,writeHead);volumeFrame.observe(work,true);}catch(e){stopLive();fail(e);return;}writeHead=(writeHead+1)%n;renderer.count=Math.min(n,renderer.count+1);renderer.head=renderer.count===n?writeHead:0;lastLive=lastLive<0||now-lastLive>liveInterval*2?now:lastLive+liveInterval;dirty=true;}if(video.requestVideoFrameCallback)liveCallback=video.requestVideoFrameCallback(capture);else liveTimer=setTimeout(()=>capture(performance.now()),16);};capture(performance.now());stream.getVideoTracks()[0].onended=()=>{stopLive();status('Camera disconnected. The captured volume is still available.');};}catch(e){if(acquired)acquired.getTracks().forEach(t=>t.stop());if(token===job){stopLive();setBusy(false);fail(e.name==='NotAllowedError'?Error('Camera access was denied. You can open a local video instead.'):e);}}}
$('camera').onclick=()=>{if(stream){job++;stopLive();status('Camera stopped. You can explore the captured volume.');}else startCamera();};
$('freeze').onclick=()=>{frozen=!frozen;$('freeze').textContent=frozen?'Resume capture':'Freeze buffer';if(!frozen)lastLive=-1;};
function recordingControls(on){for(const id of ['demo','file','camera','rebuild','quality','start','duration','outputAR','outputRes'])$(id).disabled=on;$('record').classList.toggle('recording',on);$('record').textContent=on?'■ Stop recording':'● Record MP4';if(!on&&stream)$('start').disabled=true;}
function stopRecord(){if(recorder?.state==='recording')recorder.stop();}
$('record').onclick=()=>{if(recorder?.state==='recording'){stopRecord();return;}if(!renderer.count)return;try{if(!window.MediaRecorder||!$('output').captureStream)throw Error('This browser does not support canvas recording.');renderer.render(s);const mime=mp4Type();if(!mime)throw Error('MP4 recording is unavailable. Open this page in an up-to-date Chrome or Edge with H.264 support.');recordStream=$('output').captureStream(30);recorder=new MediaRecorder(recordStream,{mimeType:mime,videoBitsPerSecond:12000000});recordChunks=[];if(recordURL){URL.revokeObjectURL(recordURL);recordURL=null;}$('download').hidden=true;recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data);};recorder.onerror=e=>{fail(e.error??Error('Recording failed'));stopRecord();};recorder.onstop=()=>{const blob=new Blob(recordChunks,{type:mime});recordURL=URL.createObjectURL(blob);$('download').href=recordURL;$('download').download=`time-volume-${new Date().toISOString().replaceAll(':','-')}.mp4`;$('download').hidden=false;recordingControls(false);recordStream.getTracks().forEach(t=>t.stop());$('recordStatus').textContent=`${(blob.size/1048576).toFixed(1)} MB · MP4`;recordChunks=[];status('MP4 ready. Click Download MP4 to save it.');};recorder.start(1000);recordStart=performance.now();recordingControls(true);status('Recording output. Move the slice and change effects; the frame size is locked.');dirty=true;}catch(e){recordStream?.getTracks().forEach(t=>t.stop());recordingControls(false);fail(e);}};
$('snapshot').onclick=()=>{if(!renderer.count)return;renderer.render(s,{locked:recorder?.state==='recording'});$('output').toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='time-volume-slice.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);});};
document.addEventListener('visibilitychange',()=>{lastTime=performance.now();if(document.hidden&&recorder?.state==='recording'){stopRecord();status('Recording stopped because the page was hidden.');}});
volume.addEventListener('webglcontextlost',e=>{e.preventDefault();job++;stopLive();stopRecord();setBusy(false);status('The graphics context was lost. Reload and choose a smaller frame buffer.',true);});
function tick(now){requestAnimationFrame(tick);if(!renderer||document.hidden){lastTime=now;return;}const elapsed=lastTime?Math.max(0,(now-lastTime)/1000):0;const dt=Math.min(.05,elapsed);lastTime=now;const recording=recorder?.state==='recording';if(scan&&!busy){const next=advanceScan(s.position,scanDirection,elapsed,clipSeconds,scanRate);s.position=next.position;scanDirection=next.direction;sliders.get('position').sync();dirty=true;}if($('animate').checked&&s.effect!==0){s.phase=((s.phase+elapsed*s.animationSpeed)%1+1)%1;sliders.get('phase').sync();dirty=true;}if(spin.some(Boolean)){renderer.yaw+=spin[0]*dt;renderer.pitch+=spin[1]*dt;dirty=true;}
if((dirty||recording)&&now-lastRender>=(busy?300:1000/30)&&renderer.count){try{renderer.render(s,{locked:recording});volumeFrame.draw(renderer);$('outputSize').textContent=`${renderer.ow} × ${renderer.oh}`;fitOutputFrame();dirty=false;framesRendered++;lastRender=now;}catch(e){fail(e);dirty=false;}}
if(now-lastStats>1000){const fps=Math.round(framesRendered*1000/(now-lastStats));$('stats').textContent=`${renderer.count} frames · ${fps?fps+' fps':'ready'}`;framesRendered=0;lastStats=now;}if(recording){const sec=(now-recordStart)/1000;$('recordStatus').textContent=`REC ${Math.floor(sec/60)}:${String(Math.floor(sec%60)).padStart(2,'0')} · 30 fps`;if(sec>=180){stopRecord();status('Recording stopped at 3 minutes. Save the file before starting another.');}}}
try{renderer=new Renderer(volume,$('output'));selectEffect(0);requestAnimationFrame(tick);load('demo.mp4','Demo / SHVETS production',true);}catch(e){$('empty').hidden=false;$('empty').querySelector('strong').textContent='Unable to start the renderer';$('loadText').textContent=e.message;$('progress').hidden=true;fail(e);}
window.addEventListener('pagehide',()=>{stopLive();stopRecord();});

